import {chapterFiveErrands} from './chapter-five-errands.js';
import {npcDialogue} from './npc-personality.js';
import {addItem,countItem,removeItem,ITEMS} from './inventory.js';
import {travelPose} from './travel-routes.js';
import {c5CartPosition} from './chapter-five-scenery.js';
import {orderErrand} from './order-errand.js';
const objectives={road:'Поговорите с обозницей Боргой на Каменном разъезде',escort:'Защитите обоз и доведите его до Рудного Брода',assault:'Очистите заставу на Каменном разъезде',arrival:'Поговорите со старостой Дурном в Рудном Броде',investigate:'Выясните, кто подделывает накладные: книга, повариха и механик',accuse:'Покажите доказательства приказчику Эрну',sluice:'Запустите насосы Нижней плавильни: пар → вода → тяга',rescue:'Найдите пленников в восточном крыле плавильни',boss:'Победите Моркана в глубине плавильни',boss_loot:'Подберите печать Моркана',escape:'Вернитесь с пленниками в Рудный Брод',return:'Поговорите со старостой Дурном',report:'Вернитесь к Воссу в Орден',done:'Глава 5 завершена · отдохните и подготовьтесь к дороге на Чёрную корону'};
const fresh=()=>({stage:'idle',route:null,roadOpen:false,permit:false,clues:0,cart:0,waves:0,valve:0,freed:false,choice:null,diverted:false,hunt:'idle',huntStart:[0,0]});
export function chapterFiveQuest(h){const {p,slots,world,legacy,show,close,sync,sound,reward,shop,lootMenu,storageMenu,stored=()=>[],bags=()=>[]}=h;let state=fresh();const active=()=>p.stage==='chapter_five',errand=orderErrand({...h,changed:()=>{flags();sync()}}),errands=chapterFiveErrands(h);
 function flags(){world?.setStory({...world.storyState?.(),...errands.flags(),orderErrand:p.orderErrand,parcelMask:p.orderParcelMask,lodging:p.rewards.includes('c3-scout'),c5Stage:state.stage,c5Cart:state.cart,c5Freed:state.freed,c5Valve:state.valve>=3,c5Boss:['boss','boss_loot'].includes(state.stage)})}
 const advance=s=>{state.stage=s;flags();sync();sound()};
 function begin(){if(!p.rewards.includes('c4-final'))return false;p.stage='chapter_five';if(state.stage==='idle')state.stage='road';flags();sync();sound();show('Глава 5. Дорога под горой','Восс: «К Чёрной короне ведёт тоннель дварфов. Но они закрыли его: на дороге пропадают обозы и люди. Нам нужен проход, им нужна помощь. Начни с обозницы Борги на Каменном разъезде. Новые ворота у южного двора, справа от входа. И загляни в оружейную — там опаснее, чем в заводях».');return true}
 function talk(n){const social=npcDialogue(p,n,show,close),say=(name,text,choices=[])=>social(name,text,[...choices,...errands.choices(n)]);if(n.id==='c3-commander'){if(state.stage==='report'){reward(p,'c5-report','quest',2400);advance('done');return say(n.name,'Значит, Моркан отправлял пленников в Чёрную корону, а среди его покупателей были наши снабженцы. Копии накладных останутся у меня. Людям, которые в них названы, пока ни слова.\n\nДурн дал нам проход под горой. Теперь нужны припасы и люди, которые не продадут отряд по дороге. Ты заслужил отдых и плату. Следующий поход будет уже к крепости Дракулы.')}return say(n.name,state.stage==='done'?'Дурн держит тоннель для нас. Я собираю обоз, а ты пока приведи в порядок снаряжение. На голодный желудок и с дырой в броне к Дракуле не ходят.':'Борга на Каменном разъезде, Дурн — в Рудном Броде. Не обещай им ничего от имени Ордена. Обещаний у них уже полный склад.')}
  if(n.id==='c3-quartermaster'&&errand.talk(n.name))return;
  if(n.id==='c3-quartermaster'||n.id==='c3-doctor')return shop('order_supplies');if(n.id==='c3-armorer')return shop('order_smith');
  if(n.id==='c3-c5-caravan'){if(state.stage==='road')return say(n.name,'Семь возов вывела, один довезла. На заставе требуют «дорожный сбор», потом забирают и деньги, и груз. Выбор простой: идёшь с моим обозом, прикрываешь от засад — или идёшь туда и объясняешь, что сбор отменяется. Только во втором случае объясняй убедительно.',[['Проведу обоз',()=>{state.route='escort';advance('escort');close()}],['Выбью заставу силой',()=>{state.route='assault';advance('assault');close()}],['Надо подготовиться',close]]);return say(n.name,state.roadOpen?'Дорога свободна. В Рудном Броде ищи Дурна — низкий, сердитый, возле ворот. Хотя это половина города.':'Держись рядом с повозкой. Увидишь людей с цепями — не жди, пока они представятся.')}
  if(n.id==='c3-c5-mayor'){if(state.stage==='arrival'){reward(p,'c5-road','quest',state.route==='assault'?2000:1200);if(state.route==='assault')reward(p,'c5-assault-premium','quest',0);advance('investigate');return say(n.name,'Борга рассказала. Спасибо. В тоннель пока не пущу: мои рабочие исчезают в нижней плавильне. По бумагам они там получают двойное жалованье. Домой деньги почему-то не приносят.\n\nПроверь книгу у склада, поговори с поварихой Нарой и механиком Таром. Потом спрашивай Эрна, нашего приказчика. Он очень любит бумаги. Пусть хоть раз они послужат нам.')}
   if(state.stage==='return'){if(state.choice==='fight'){const id=p.classId+'_warden';if(!countItem(slots,id)&&!addItem(slots,id))return say(n.name,'Награда никуда не денется. Освободи ячейку под оружие.');reward(p,'c5-warden-bonus','quest',600)}reward(p,'c5-rescue','quest',state.choice==='fight'?2500:1800);advance('report');return say(n.name,state.choice==='fight'?'Горн и Мирен дома. Моркан больше никого не увезёт. Возьми его оружие, Руна уже привела его в порядок. Тоннель для Ордена откроем, но только под моим надзором. А Воссу отнеси копии накладных: там печати его снабженцев.':'Оба вернулись. Моркан ещё жив, но сегодня он недосчитался людей. Для меня это важнее его головы. Тоннель откроем под нашей охраной. Отнеси Воссу копии накладных — пусть разберётся, почему его люди платили сборщику.')}
   return say(n.name,'Кузница на западе, травница на востоке, Тар у водяного колеса. Здесь живут не только дварфы. Сумеречники шьют, торгуют и платят за жильё ровно как остальные. Только уши в дверь иногда не проходят.')}
  if(n.id==='c3-c5-smith')return say(n.name,'Клинки, луки, посохи. И броня, которая держит удар, а не только красиво называется. Плавильня теперь опасная: не экономь на нагруднике.',[['Посмотреть снаряжение',()=>shop('order_deep_smith')],['До встречи',close]]);
  if(n.id==='c3-c5-healer')return say(n.name,'Да, у меня длинные уши. Нет, на слух я переломы не определяю. Если идёшь в шахту — возьми лекарства. И поешь. Эль за обед не считается.',[['Купить припасы',()=>shop('order_deep_supplies')],['Кто такие сумеречники?',()=>say(n.name,'Наши поселения были в долинах, пока туда не пришли сборщики Дракулы. Теперь многие живут здесь. Дурн дал нам мастерские, мы починили ему водяные колёса. Бывает и такая торговля, без меча у горла.')],['До встречи',close]]);
  if(n.id==='c3-c5-witness'){state.clues|=2;sync();return say(n.name,'Эрн просил готовить на двадцать работников. Потом на десять. Потом велел не задавать вопросов, куда делись остальные. Я-то не задаю. Просто перестала класть ему мясо. Пусть тоже не задаёт вопросов.')}
  if(n.id==='c3-c5-engineer'){state.clues|=4;sync();return say(n.name,'Вчера Эрн заказал замки. Снаружи открываются, изнутри нет. Для склада, говорит. Склад у него, видимо, очень хочет сбежать.\n\nНасосы в плавильне запускают по порядку: сбросить ПАР, подать ВОДУ, включить ТЯГУ. Перепутаешь — жди, пока остынет. Рычаги подписаны, для тех, кто не механик.')}
  if(n.id==='c3-c5-clerk'){if(['investigate','accuse'].includes(state.stage)){if(state.clues!==7)return say(n.name,'Подпись старосты есть? Тогда не отвлекайте. У меня учёт.');return say(n.name,'Ну и что вы нашли? Ошибки в книге? Бывают. Замки? Бывают тоже. А повариха вообще на меня сердита.',[['Книга поддельная, работников запирают. Где они?',()=>{state.permit=true;reward(p,'c5-evidence','quest',1600);advance('sluice');say(n.name,'В нижней плавильне. Я делал накладные, Моркан увозил людей. У него печать Дракулы, я хотел жить. Ключ от клетки я оставлю Тару, он передаст тебе. Только не говори старосте, что я ещё здесь.') }],['Сначала проверю ещё раз',close]])}return say(n.name,'Мне велели ждать разбирательства. На удивление, это хуже, чем работать.')}
  if(n.id==='c3-c5-prisoner'||n.id==='c3-c5-dusk-prisoner'){if(state.stage==='rescue')return say(n.name,'Ты с ключом? Отлично. Нас держали для отправки в Чёрную корону. В накладных писали «руда». Я руду добываю сорок лет, у неё таких разговорчивых ушей не бывает.\n\nМоркан в дальнем цехе. Можно отвлечь охрану паром и уйти, а можно закончить с ним. Если полезешь — мы подождём у выхода.',[['Открою сброс пара, уходите',()=>{state.choice='quiet';state.freed=true;advance('escape');say(n.name,'Сброс пара в западном крыле, на карте отмечен. Как включишь, мы пойдём к главному выходу. Сам тоже не задерживайся.')}],['Сначала разберусь с Морканом',()=>{state.choice='fight';state.freed=true;advance('boss');close()}],['Подготовлюсь и вернусь',close]]);return say(n.name,state.freed?'Выход знаем. Не стой под трубами, когда пойдёт пар.':'Мы здесь. Если у тебя ключ — говори тише, пожалуйста.')}
  if(n.id==='c3-c5-hermit')return say(n.name,'Колесо встало, лес сырой, ещё и волки повадились к дровам. У тебя тоже новости плохие? Тогда по очереди.');
  if(n.id==='c3-c5-town-0'){if(state.hunt==='idle')return say(n.name,'Нужна работа? Шесть наёмников и три голема на дороге и в плавильне. Големов не жалей: их собирали под надзором Моркана, руки у них явно не для добычи руды.',[['Возьмусь за охоту',()=>{state.hunt='active';state.huntStart=[world.killCount('c5_raider'),world.killCount('c5_brute')];sync();sound();close()}],['Не сейчас',close]]);const counts=huntCounts();if(state.hunt==='active'&&counts[0]>=6&&counts[1]>=3){reward(p,'c5-hunt','quest',900);state.hunt='done';sync();return say(n.name,'Дорога стала тише. Даже слишком: теперь слышно, как староста ругается. Вот твои деньги.')}return say(n.name,'Пока счёт такой: наёмники '+Math.min(6,counts[0])+' / 6, големы '+Math.min(3,counts[1])+' / 3.')}
  return say(n.name,n.race==='dusk'?'Когда переехали, Дурн предложил обрезать дверной косяк. До этого все предлагали обрезать мне уши. Уже за одно это я плачу налоги без споров.':'Работаем, ругаемся, чиним старое. Если услышишь взрыв — сначала спроси Тара. Может, он как раз добился того, чего хотел.');
 }
 function tick(dt=0){if(!active())return;const zone=world.mode;if(state.stage==='escort'&&zone==='highroad'){const cart=c5CartPosition(state.cart),d=Math.hypot(h.camera?.position.x-cart[0]||0,h.camera?.position.z-cart[2]||0);if(d<22&&!world.groupAlive('c5-escort')){state.cart=Math.min(1,state.cart+dt/60);world.cartPose(state.cart)}if(state.waves<2&&state.cart>=(state.waves? .65:.25)){world.c5Wave(state.waves++);sync()}if(state.cart>=1){state.roadOpen=true;advance('arrival');show('Обоз у ворот','Борга: «Довезли! Даже лишний мешок нашёлся. Если в нём кто-то прячется, пусть сначала разгрузит остальные».')}}
  if(state.stage==='assault'&&world.groupDefeated('c5-road')){state.roadOpen=true;advance('arrival');show('Застава свободна','Можно пройти в Рудный Брод. За силовой путь полагается повышенная плата. Борга уже отправила старосте весть.')}
  if(state.stage==='investigate'&&state.clues===7)advance('accuse');if(state.stage==='boss'&&world.findActor('c5_overseer')?.hp===0)advance('boss_loot');if(state.stage==='boss_loot'&&countItem(slots,'c5_seal'))advance('escape');if(state.stage==='boss_loot'&&!countItem(slots,'c5_seal')&&!countItem(stored(),'c5_seal')&&!bags().some(b=>countItem(b.items||[],'c5_seal')))world.ensureQuestDrop('c5_seal','c5_overseer');if(state.stage==='escape'&&state.freed&&(state.choice==='fight'||state.diverted)&&zone==='stonehaven')advance('return');flags();world.updateUI(marker);
 }
 function interact(){if(!active())return false;if(!world.inside){const a=legacy?.action();if(legacy?.mode==='city'&&a?.to==='pass'){world.enter('pass');close();return true}return false}const a=world.action();if(!a)return false;
  if(a.type==='npc'){talk(a.npc);return true}if(a.type==='travel'){if(a.to==='valden'){world.leave();sync();return true}if(a.to==='stonehaven'&&world.mode==='highroad'&&!state.roadOpen||a.to==='underworks'&&!state.permit){show('Ворота','Ворота не поддаются.');return true}world.resetCombat();world.enter(a.to,travelPose('c3_'+world.mode,'c3_'+a.to));flags();close();sync();return true}
  if(a.type==='storage'){storageMenu?.(a.chest);return true}if(a.type==='chest'){lootMenu(world.openChest(a.chest));return true}if(a.type==='checkpoint'){p.checkpoint={id:'c3-'+world.mode,zone:'c3_'+world.mode,position:[a.fire.x+2.2,1.7,a.fire.z]};sync();sound();show('Контрольная точка','Здесь можно передохнуть и установить точку возвращения.');return true}
  if(errands.interact(a)){flags();return true}if(a.type==='c5-ledger'){if(state.stage==='investigate'){state.clues|=1;sync()}show('Складская книга','На последних страницах подпись Дурна скопирована через промокашку. Число работников совпадает с числом мешков «руды», отправленных Моркану.');return true}
  if(a.type.startsWith('c5-valve-')){if(state.stage!=='sluice'){show('Насосы',state.valve>=3?'Насосы работают.':'На механизме пломба.');return true}const i=Number(a.type.slice(-1));if(i===state.valve){state.valve++;sound();if(state.valve===3){advance('rescue');show('Насосы запущены','Вода уходит из нижних коридоров. Центральная решётка открылась.')}else{sync();show('Рычаг','Готово. Следующий: '+['ПАР','ВОДА','ТЯГА'][state.valve]+'.')}}else{state.valve=0;sync();show('Сброс давления','Трубы загрохотали. Автоматика сбросила рычаги. Начни с пара, потом вода, затем тяга.')}return true}
  if(a.type==='c5-cell'){talk(world.citizens.find(n=>n.id==='c3-c5-prisoner'));return true}if(a.type==='c5-diversion'){if(state.stage==='escape'&&state.choice==='quiet'){state.diverted=true;sync();world.pacify('underworks',45);show('Пар в цехе','Охрана отступила от труб. Пленники уходят к главному выходу. Возвращайся в Рудный Брод.')}else show('Сброс пара','Сейчас сбрасывать давление не нужно.');return true}return false;
 }
 function huntCounts(){return [Math.max(0,world.killCount('c5_raider')-state.huntStart[0]),Math.max(0,world.killCount('c5_brute')-state.huntStart[1])]}
 function marker(id){const extra=errand.marker(id);if(extra)return extra;if(id==='c3-commander'&&['report','done'].includes(state.stage))return state.stage==='report'?{symbol:'?'}:null;if(id==='c3-c5-caravan'&&state.stage==='road')return {symbol:'!'};if(id==='c3-c5-mayor'&&['arrival','return'].includes(state.stage))return {symbol:'?'};if(id==='c3-c5-clerk'&&state.stage==='accuse')return {symbol:'?'};if(id==='c3-c5-prisoner'&&state.stage==='rescue')return {symbol:'!'};if(id==='c3-c5-town-0'&&state.hunt!=='done')return {symbol:state.hunt==='active'&&huntCounts()[0]>=6&&huntCounts()[1]>=3?'?':'!',optional:true};return errands.marker(id)}
 function navigation(){const z=world.mode,s=state.stage;if(!world.inside)return legacy?.mode==='city'?[2425,-214]:legacy?.mode==='road'?[2000,-234]:[0,-118];let dest='highroad',target=[6406,-54];if(['arrival','return','investigate','accuse'].includes(s)){dest='stonehaven';target=s==='investigate'?[state.clues&1?state.clues&2?6771:6760:6839,state.clues&1?state.clues&2?-149:-195:-180]:s==='accuse'?[6830,-192]:[6808,-58]}else if(['sluice','rescue','boss','boss_loot','escape'].includes(s)){dest='underworks';target=s==='sluice'?[7190+state.valve*10,-52]:s==='rescue'?[7262,-193]:s==='boss'||s==='boss_loot'?[7200,-278]:state.choice==='quiet'&&!state.diverted?[7108,-217]:[7200,-20]}else if(s==='report'||s==='done'){dest='fortress';target=[4006,-77]}else if(s==='escort'){const c=c5CartPosition(state.cart);target=[c[0],c[2]]}else if(s==='assault')target=[6364,-170];if(z===dest)return target;if(z==='pass')return [3600,-258];if(z==='fortress')return [4034,-38];if(z==='highroad')return dest==='fortress'?[6400,-20]:[6400,-288];if(z==='stonehaven')return dest==='underworks'?[6800,-258]:[6800,-20];return [7200,-20]}
 return {begin,active,flags,tick,interact,marker,navigation,objective:()=>active()?'Дорога под горой\n'+objectives[state.stage]:null,optional:()=>[errand.objective(),errands.objective(),state.hunt==='active'?'Ночная смена: наёмники '+Math.min(6,huntCounts()[0])+' / 6 · големы '+Math.min(3,huntCounts()[1])+' / 3':''].filter(Boolean).join('\n'),snapshot:()=>({...state,huntStart:[...state.huntStart]}),restore(s){state={...fresh(),...s,huntStart:[...(s?.huntStart||[0,0])]};if(active())flags()},get state(){return state}};
}
